using System;
using System.Drawing;
using System.Windows.Forms;
namespace VinsPDF {
internal sealed partial class MainForm {
 readonly PageCanvas secondCanvas=new PageCanvas();bool twoPages;int secondVersion,secondRenderedVersion;
 void InstallLayout(){var layout=new ToolStripDropDownButton("Layout"){ForeColor=ForeColor};layout.DropDownItems.Add("Single page",null,delegate{SetTwoPages(false);});layout.DropDownItems.Add("Two pages",null,delegate{SetTwoPages(true);});bar.Items.Insert(1,layout);secondCanvas.Dock=DockStyle.Right;secondCanvas.Visible=false;documentArea.Controls.Add(secondCanvas);documentArea.Resize+=delegate{secondCanvas.Width=Math.Max(1,documentArea.Width/2);};secondCanvas.ViewChanged+=delegate{RenderSecond();};secondCanvas.PageStep+=ScrollPage;}
 internal void SetTwoPages(bool value){if(!FinishInline())return;if(value&&canvas.Editing)ToggleEditing();twoPages=value;secondCanvas.Visible=value;secondCanvas.Width=Math.Max(1,documentArea.Width/2);canvas.Fit("page");if(sizes!=null){if(value&&pageIndex+1<sizes.Length){secondCanvas.FitMode="page";secondCanvas.SetPage(sizes[pageIndex+1],null);}else secondCanvas.ClearPage();RenderSecond();}RequestRender();}
 void RenderSecond(){int version=++secondVersion;if(!documentVisible)return;if(!twoPages||sizes==null||pageIndex+1>=sizes.Length){secondCanvas.ClearPage();return;}int index=pageIndex+1,token=generation;SizeF displaySize=sizes[index];if(rotations[index]%2!=0)displaySize=new SizeF(displaySize.Height,displaySize.Width);if(!secondCanvas.HasPage||secondCanvas.PageSize!=displaySize){secondCanvas.SetPage(displaySize,null);return;}Rectangle page=secondCanvas.PageRectangle,area=Rectangle.Intersect(page,secondCanvas.ClientRectangle);if(area.Width<1||area.Height<1)return;worker.Secondary(delegate(PdfEngine e){if(version!=secondVersion||token!=generation)return;try{Bitmap image=e.Render(index,rotations[index],area.Width,area.Height,page.X-area.X,page.Y-area.Y,page.Width,page.Height,delegate{return version!=secondVersion||token!=generation||!documentVisible;});Post(delegate{if(version!=secondVersion||token!=generation){image.Dispose();return;}secondCanvas.SetDetail(image,area,page);secondRenderedVersion=version;},image);}catch(OperationCanceledException){}catch(Exception ex){string message=ex.Message;Post(delegate{if(token==generation)status.Text="Second page: "+message;},null);} });}
}
}
